using Check=std::function<void(bool,const char*)>;
class Host final:public CFrameWnd {void PostNcDestroy()override{}};
class ActivationBlock {HHOOK hook_;public:ActivationBlock(){hook_=SetWindowsHookEx(WH_CBT,[](int n,WPARAM w,LPARAM l)->LRESULT{return n==HCBT_ACTIVATE?1:CallNextHookEx(nullptr,n,w,l);},nullptr,GetCurrentThreadId());if(!hook_)throw std::runtime_error("Cannot isolate parity fixture");}~ActivationBlock(){UnhookWindowsHookEx(hook_);}};
bool Reject(const std::function<void()>& f){try{f();return false;}catch(const std::exception&){return true;}}
sct::core::DocumentState Source(bool object=true){sct::core::Image image;image.Create(320,220);for(int y=30;y<170;++y)for(int x=20;x<280;++x){auto* p=image.Row(y)+x*4;p[0]=20;p[1]=40;p[2]=180;p[3]=255;}auto state=sct::core::Document(std::move(image)).State();if(object){sct::core::Annotation a;a.tool=sct::core::Tool::Rectangle;a.rect={50,60,100,100};state.objects.push_back(a);}return state;}
void Core(Check check){using namespace sct::core;
 for(POINT p:std::vector<POINT>{{140,90},{20,90},{20,10},{140,10},{300,300},{-90,-90}}){const auto end=SquareEnd({80,60},p,160,120);check(abs(end.x-80)==abs(end.y-60)&&end.x>=0&&end.y>=0&&end.x<=160&&end.y<=120,"square constraint preserves all quadrants and frozen image edges");const auto line=AngleEnd({80,60},p,160,120);check((line.x==80||line.y==60||abs(line.x-80)==abs(line.y-60))&&line.x>=0&&line.y>=0&&line.x<=160&&line.y<=120,"angle snap retains45-degree directions and bounds");}
 for(int handle:{0,1,2,3,5,6,7,8}){const auto r=AspectResize({20,30,120,80},handle,{170,145});check(r.right>r.left&&r.bottom>r.top&&abs((r.right-r.left)-2*(r.bottom-r.top))<=1,"all eight resize handles retain original aspect ratio with bounded rounding");}
 check(Reject([]{AspectResize({0,0,0,10},2,{10,10});})&&Reject([]{AspectResize({0,0,10,10},4,{10,10});})&&Reject([]{AspectResize({0,0,10,10},8,{2000000,10});}),"invalid or over-limit constraints fail before a model mutation");
 Image image;image.Create(10,8);for(size_t i=0;i<image.pixels.size();i+=4){image.pixels[i]=71;image.pixels[i+3]=0;}for(int y=2;y<6;++y)for(int x=3;x<8;++x){auto* p=image.Row(y)+x*4;p[0]=p[1]=p[2]=60;p[3]=255;}const auto original=image.pixels;const RECT expected{3,2,8,6};auto found=DetectCrop(image,true,0);check(EqualRect(&found,&expected)&&image.pixels==original,"transparent crop ignores hidden RGB and never changes source pixels");found=DetectCrop(image,false,0);check(EqualRect(&found,&expected),"corner-color crop handles transparent corner RGB correctly");
 Image solid;solid.Create(10,8);found=DetectCrop(solid,false,0);check(IsRectEmpty(&found),"uniform images produce no destructive empty crop");auto* pixel=solid.Row(4)+5*4;pixel[0]=250;pixel[1]=pixel[2]=255;found=DetectCrop(solid,false,0);check(found.left==5&&found.top==4&&found.right==6&&found.bottom==5,"exact corner-color mode detects a one-pixel difference");found=DetectCrop(solid,false,5);check(IsRectEmpty(&found),"color tolerance is applied to border detection");check(Reject([&]{DetectCrop(solid,true,256);})&&Reject([]{Image invalid;DetectCrop(invalid,true,0);}),"invalid crop scan input and tolerance are rejected");
}
